CREATE TEMPORARY TABLE temp_sales AS
SELECT * FROM production.sales
WHERE region = 'North America';

// Simplified Logic: Find 1st day, find 1st Friday, add 14 days
DATEADD('day', 14,
  DATEADD('day',
    (7 - DATEPART('weekday', DATETRUNC('month', [Order Date])) + 6) % 7,
    DATETRUNC('month', [Order Date])
  )
)

IF [Order Date] = { FIXED [Customer Name] : MAX([Order Date]) }
THEN [Sales]
END

const viz = document.querySelector('tableau-viz');
viz.addEventListener('firstinteractive', () => {
  const sheet = viz.workbook.activeSheet;
  sheet.applyFilterAsync('Region', ['West'], 'replace');
});
